class Box
    public define content as integer;
endClass

subroutine Swap(boxA as Box, boxB as Box)
    define auxiliary as integer;
    auxiliary <- boxA.content;
    boxA.content <- boxB.content;
    boxB.content <- auxiliary;
endSubroutine

algorithm RunBoxSwap
    define v1 as integer;
    define v2 as integer;
    define box1 as Box;
    define box2 as Box;
    read v1;
    read v2;
    box1 <- new Box();
    box2 <- new Box();
    box1.content <- v1;
    box2.content <- v2;
    Swap(box1, box2);
    write box1.content;
    write box2.content;
endAlgorithm
